	@Test
	void aggregateWorkersOverlapInsideDisjointNodeDomainCounts() {
		RunResult run = execute(false, true);

		assertPartitionAccounting(run);
		assertOverlapContract(run);
	}

	@Test
	void serializedCountWorkDoesNotSatisfyOverlapContract() {
		RunResult run = execute(true, false);

		assertPartitionAccounting(run);
		assertThat(run.countPartitionPeak).as("the negative control serializes only actual source work").isEqualTo(1);
		assertThatThrownBy(() -> assertOverlapContract(run))
				.as("the same overlap assertion must reject serialized countPartition work")
				.isInstanceOf(AssertionError.class)
				.hasMessageContaining("actual countPartition work must overlap");
	}

	private static void assertOverlapContract(RunResult run) {
		assertThat(run.countPartitionPeak)
				.as("actual countPartition work must overlap; serialized negative control would fail here")
				.isGreaterThanOrEqualTo(2);
		assertThat(run.peakActiveWorkers)
				.as("parallel aggregate telemetry must observe at least two active workers")
				.isGreaterThanOrEqualTo(2);
		assertThat(run.workerOverlapNanos).as("worker intervals must overlap").isPositive();
	}

	private static void assertPartitionAccounting(RunResult run) {
		assertThat(run.resultCount).isEqualTo(EXPECTED_INTERSECTION_COUNT);
		assertThat(run.parallelRuns).isPositive();
		assertThat(run.selectedOperator).isEqualTo("EnumerateNodeDomainIntersection");
		assertThat(run.partitionCount).isEqualTo(PARTITIONS);
		assertThat(run.countPartitionCalls).containsOnly(1);
		assertThat(run.ownersByPartition.keySet()).containsExactlyInAnyOrderElementsOf(
				java.util.stream.IntStream.range(0, PARTITIONS).boxed().toList());
		assertThat(run.workersStarted).isGreaterThanOrEqualTo(2);
		assertThat(run.workersWithNonZeroWork).isEqualTo(run.workersStarted);
		assertThat(run.partitionsByWorker).hasSize(run.workersStarted);
		assertThat(run.partitionsByWorker.values()).allMatch(partitions -> !partitions.isEmpty());

		Map<Integer, Long> telemetryMorsels = parseMorsels(run.morselsPerWorker);
		List<Long> sourcePartitions = run.partitionsByWorker.values()
				.stream()
				.map(partitions -> (long) partitions.size())
				.sorted()
				.toList();
		assertThat(telemetryMorsels).hasSize(run.workersStarted);
		assertThat(telemetryMorsels.keySet()).containsExactlyInAnyOrderElementsOf(
				java.util.stream.IntStream.range(0, run.workersStarted).boxed().toList());
		List<Long> telemetryMorselCounts = telemetryMorsels.values().stream().sorted().toList();
		assertThat(telemetryMorselCounts).allMatch(count -> count > 0L);
		assertThat(telemetryMorselCounts.stream().mapToLong(Long::longValue).sum()).isEqualTo(PARTITIONS);
		assertThat(telemetryMorselCounts).containsExactlyElementsOf(sourcePartitions);
	}

