	private static final class IntersectionWork {
		private final boolean serializeCountPartitionWork;
		private final CountDownLatch rendezvous = new CountDownLatch(2);
		private final Set<Thread> rendezvousWorkers = ConcurrentHashMap.newKeySet();
		private final AtomicInteger active = new AtomicInteger();
		private final AtomicInteger peakActive = new AtomicInteger();
		private final AtomicIntegerArray calls = new AtomicIntegerArray(PARTITIONS);
		private final AtomicInteger nextWorkerOrdinal = new AtomicInteger();
		private final Map<Integer, Integer> ownersByPartition = new ConcurrentHashMap<>();
		private final Map<Integer, Set<Integer>> partitionsByWorker = new ConcurrentHashMap<>();
		private final long[][] intersections = new long[PARTITIONS][];
		private final Set<Long> allIntersectionNodes = new HashSet<>();
		private final Object serializedWork = new Object();
		private final boolean rendezvousEnabled;

		private IntersectionWork(boolean serializeCountPartitionWork, boolean rendezvousEnabled) {
			this.serializeCountPartitionWork = serializeCountPartitionWork;
			this.rendezvousEnabled = rendezvousEnabled;
			for (int partition = 0; partition < PARTITIONS; partition++) {
				long firstNode = (long) partition * NODES_PER_PARTITION + 1L;
				intersections[partition] = new long[] { firstNode, firstNode + 2L };
				for (long nodeId : intersections[partition]) {
					allIntersectionNodes.add(nodeId);
				}
			}
		}

		private NativeLmdbQuerySource.NodeDomainIntersection newView() {
			return new NativeLmdbQuerySource.NodeDomainIntersection() {
				@Override
				public long estimatedWork() {
					return (long) PARTITIONS * NODES_PER_PARTITION;
				}

				@Override
				public boolean contains(long nodeId) {
					return allIntersectionNodes.contains(nodeId);
				}

				@Override
				public int partitionCount() {
					return PARTITIONS;
				}

				@Override
				public long countPartition(int partition) {
					if (serializeCountPartitionWork) {
						synchronized (serializedWork) {
							return countPartitionWork(partition);
						}
					}
					return countPartitionWork(partition);
				}

				private long countPartitionWork(int partition) {
					int concurrent = active.incrementAndGet();
					peakActive.accumulateAndGet(concurrent, Math::max);
					try {
						awaitPeerWorkIfRequired();
						if (partition < 0 || partition >= PARTITIONS) {
							throw new AssertionError("invalid test partition " + partition);
						}
						int invocation = calls.incrementAndGet(partition);
						if (invocation != 1) {
							throw new AssertionError("partition " + partition + " counted more than once");
						}
						int worker = workerOrdinal(Thread.currentThread());
						Integer prior = ownersByPartition.putIfAbsent(partition, worker);
						if (prior != null) {
							throw new AssertionError("partition " + partition + " was assigned to multiple workers");
						}
						partitionsByWorker.computeIfAbsent(worker, ignored -> ConcurrentHashMap.newKeySet())
								.add(partition);

						long count = 0L;
						long firstNode = (long) partition * NODES_PER_PARTITION + 1L;
						for (int offset = 0; offset < NODES_PER_PARTITION; offset++) {
							if (allIntersectionNodes.contains(firstNode + offset)) {
								count++;
							}
						}
						return count;
					} finally {
						active.decrementAndGet();
					}
				}

				private void awaitPeerWorkIfRequired() {
					if (!rendezvousEnabled || !rendezvousWorkers.add(Thread.currentThread())) {
						return;
					}
					rendezvous.countDown();
					try {
						if (!rendezvous.await(FAILURE_GUARD_SECONDS, TimeUnit.SECONDS)) {
							throw new AssertionError(
									"parallel node-domain work did not rendezvous in countPartition");
						}
					} catch (InterruptedException interrupted) {
						Thread.currentThread().interrupt();
						throw new AssertionError("interrupted while waiting for concurrent countPartition work",
								interrupted);
					}
				}

				@Override
				public Cursor cursor(int partition) {
					long[] values = intersections[partition];
					return new Cursor() {
						private int next;
						private long current;

						@Override
						public boolean next() {
							if (next >= values.length) {
								return false;
							}
							current = values[next++];
							return true;
						}

						@Override
						public long nodeId() {
							return current;
						}
					};
				}
			};
		}

		private int workerOrdinal(Thread thread) {
			return workerOrdinals.computeIfAbsent(thread, ignored -> nextWorkerOrdinal.getAndIncrement());
		}

		private final Map<Thread, Integer> workerOrdinals = new ConcurrentHashMap<>();

		private int[] partitionCalls() {
			int[] observed = new int[PARTITIONS];
			for (int partition = 0; partition < PARTITIONS; partition++) {
				observed[partition] = calls.get(partition);
			}
			return observed;
		}

		private Map<Integer, Integer> partitionOwners() {
			return Map.copyOf(ownersByPartition);
		}

		private Map<Integer, Set<Integer>> partitionsByWorker() {
			return partitionsByWorker.entrySet()
					.stream()
					.collect(Collectors.toUnmodifiableMap(Map.Entry::getKey,
							entry -> Set.copyOf(entry.getValue())));
		}
	}

